   272	/* HEL -> Open up the connection */
   273	static UA_StatusCode
   274	processHEL(UA_Server *server, UA_Connection *connection,
   275	           const UA_ByteString *msg, size_t *offset) {
   276	    UA_TcpHelloMessage helloMessage;
   277	    UA_StatusCode retval = UA_TcpHelloMessage_decodeBinary(msg, offset, &helloMessage);
   278	    if(retval != UA_STATUSCODE_GOOD)
   279	        return retval;
   280	
   281	    /* Currently not checked */
   282	    UA_String_deleteMembers(&helloMessage.endpointUrl);
   283	
   284	    /* TODO: Use the config of the exact NetworkLayer */
   285	    if(server->config.networkLayersSize == 0)
   286	        return UA_STATUSCODE_BADOUTOFMEMORY;
   287	    const UA_ConnectionConfig *localConfig = &server->config.networkLayers[0].localConnectionConfig;
   288	
   289	    /* Parameterize the connection */
   290	    UA_ConnectionConfig remoteConfig;
   291	    remoteConfig.protocolVersion = helloMessage.protocolVersion;
   292	    remoteConfig.sendBufferSize = helloMessage.sendBufferSize;
   293	    remoteConfig.recvBufferSize = helloMessage.receiveBufferSize;
   294	    remoteConfig.maxMessageSize = helloMessage.maxMessageSize;
   295	    remoteConfig.maxChunkCount = helloMessage.maxChunkCount;
   296	    retval = UA_Connection_processHELACK(connection, localConfig, &remoteConfig);
   297	    if(retval != UA_STATUSCODE_GOOD) {
   298	        UA_LOG_INFO(server->config.logger, UA_LOGCATEGORY_NETWORK,
   299	                    "Connection %i | Error during the HEL/ACK handshake",
   300	                    connection->sockfd);
   301	        return retval;
   302	    }
   303	
   304	    /* Build acknowledge response */
   305	    UA_TcpAcknowledgeMessage ackMessage;
   306	    memcpy(&ackMessage, localConfig, sizeof(UA_TcpAcknowledgeMessage)); /* Same struct layout.. */
   307	    UA_TcpMessageHeader ackHeader;
   308	    ackHeader.messageTypeAndChunkType = UA_MESSAGETYPE_ACK + UA_CHUNKTYPE_FINAL;
   309	    ackHeader.messageSize = 8 + 20; /* ackHeader + ackMessage */
   310	
   311	    /* Get the send buffer from the network layer */
   312	    UA_ByteString ack_msg;
   313	    UA_ByteString_init(&ack_msg);
   314	    retval = connection->getSendBuffer(connection, connection->config.sendBufferSize, &ack_msg);
   315	    if(retval != UA_STATUSCODE_GOOD)
   316	        return retval;
   317	
   318	    /* Encode and send the response */
   319	    UA_Byte *bufPos = ack_msg.data;
   320	    const UA_Byte *bufEnd = &ack_msg.data[ack_msg.length];
   321	
   322	    retval = UA_TcpMessageHeader_encodeBinary(&ackHeader, &bufPos, bufEnd);
   323	    if(retval != UA_STATUSCODE_GOOD) {
   324	        connection->releaseSendBuffer(connection, &ack_msg);
   325	        return retval;
   326	    }
   327	
   328	    retval = UA_TcpAcknowledgeMessage_encodeBinary(&ackMessage, &bufPos, bufEnd);
   329	    if(retval != UA_STATUSCODE_GOOD) {
   330	        connection->releaseSendBuffer(connection, &ack_msg);
   331	        return retval;
   332	    }
   333	    ack_msg.length = ackHeader.messageSize;
   334	    return connection->send(connection, &ack_msg);
   335	}
